import math
from itertools import permutations

def is_perfect_square(n):
    if n < 0:
        return False
    sqrt_n = int(math.isqrt(n))
    return sqrt_n * sqrt_n == n

def check_permutation(n, p):
    current_sum = 0
    for i in range(n):
        current_sum += p[i]
        if is_perfect_square(current_sum):
            return False
    return True

def is_cool(n):
    """Checks if an integer n is cool by trying all permutations."""
    # For small n (up to maybe 10 or 11), checking all permutations is feasible.
    # For larger n, we must use backtracking, but since we are limited to n=30,
    # let's implement the backtracking approach which is necessary for feasibility.

    if n == 0: return False

    numbers = list(range(1, n + 1))

    memo = {} # Memoization might not be standard for this type of search, but good practice.

    def backtrack(current_permutation, available_mask, current_sum):
        if len(current_permutation) == n:
            return True

        # available_mask is a bitmask where the i-th bit is set if number i+1 is available.

        for i in range(n):
            if (available_mask >> i) & 1: # Check if number i+1 is available
                x = i + 1
                new_sum = current_sum + x

                if not is_perfect_square(new_sum):
                    new_mask = available_mask ^ (1 << i)

                    if backtrack(current_permutation + [x], new_mask, new_sum):
                        return True
        return False

    # Start state: empty permutation, all numbers available (mask 2^n - 1), sum 0
    return backtrack([], (1 << n) - 1, 0)

# --- Execution ---
N_MAX = 30
cool_integers = []
non_cool_integers = []

for n in range(1, N_MAX + 1):
    if is_cool(n):
        cool_integers.append(n)
    else:
        non_cool_integers.append(n)

print(f"Cool Integers (up to {N_MAX}): {cool_integers}")
print(f"Non-Cool Integers (up to {N_MAX}): {non_cool_integers}")

# Check if the search completed successfully for larger N
